Push the new value and discard the smallest when the heap exceeds k elements. The retained heap contains the k largest values with multiplicity, so its minimum is the answer once it has k entries. Time O(n log(k+1)), space O(k).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,k; cin>>n>>k;
    priority_queue<int,vector<int>,greater<int>> top;
    for (int i=1;i<=n;++i) {
        int x; cin>>x;
        top.push(x);
        if (int(top.size())>k) top.pop();
        if (i>=k) cout<<top.top()<<'\n';
    }
}
